from pathlib import Path
import re,hashlib,json,xml.etree.ElementTree as ET
files=[Path('README.md'),Path('frontend/README.md'),Path('backend/README.md'),Path('frontend/tests/README.md')]+[p for p in Path('docs').glob('*.md')if p.name!='ai-session.md']
errors=[]
def anchors(text):
 out=[]
 for line in text.splitlines():
  if re.match(r'^#{1,6}\s',line):
   h=re.sub(r'^#+\s*','',line).lower();h=re.sub(r'[^\w\- ]','',h).strip().replace(' ','-');out.append(h)
 return out
for p in files:
 s=p.read_text()
 for link in re.findall(r'\[[^\]]*\]\(([^)]+)\)',s):
  if re.match(r'[a-z]+:',link):continue
  name,sep,anchor=link.partition('#');target=p.parent/name if name else p
  if target.name=='.gitignore'or'.git'in target.parts:continue
  if not target.exists():errors.append([str(p),link,'missing path'])
  elif anchor and target.suffix=='.md'and anchor not in anchors(target.read_text()):errors.append([str(p),link,'missing heading'])
 if re.search('[А-Яа-яЁё]',s):errors.append([str(p),'non-English text'])
for cfg in ['phpunit.xml','offers.xml','fingerprints.xml','checkout.xml','checkout-services.xml','payments.xml']:
 p=Path('backend/tests/Postgres')/cfg;tree=ET.parse(p)
 for element in tree.findall('.//file'):
  assert(p.parent/element.text).is_file(),(cfg,element.text)
for path in ['scripts/tests/frontend-checkout-e2e.sh','scripts/tests/production-db.tests.ps1','scripts/production-db.ps1','backend/Dockerfile.prod','frontend/vercel.json','compose.search-test.yaml','docker/php/entrypoint.sh']:
 assert Path(path).is_file(),path
expected=json.loads(Path('/tmp/eneba-docs-protected.json').read_text())
changed=[r for r,h in expected.items()if not Path(r).is_file()or hashlib.sha256(Path(r).read_bytes()).hexdigest()!=h]
print(json.dumps({'documents':len(files),'link_language_errors':errors,'suite_references_verified':6,'protected_files_checked':len(expected),'non_doc_changes':changed,'ai_history_and_historical_prompt_unchanged':all(hashlib.sha256(Path(r).read_bytes()).hexdigest()==expected[r]for r in ['docs/ai-session.md','docs/ai-request.txt'])},indent=2))
